import { Hono } from 'hono'
import { serve, upgradeWebSocket } from '@hono/node-server'
import { WebSocketServer } from 'ws'
import { cors } from 'hono/cors'
import { serveStatic } from '@hono/node-server/serve-static'
import { append, children, read, write } from 'lib/file'
import { format_log } from 'lib/log'
import { parse_options } from 'lib/cli'
// import * as action_index from 'action/index'
import { list as action_list, hide } from 'action/index'
import {
  deserialize,
  get_message_log_file,
  get_thread_file,
  get_thread_log_file,
  serialize,
  server_log_file,
  thread_index_file,
} from 'action/index'
import { monotonic, now } from 'lib/time'
import { random, random_id } from 'lib/random'
import {
  append_message,
  build_plain_context,
  empty_thread_structure,
} from 'utility/thread'
import { generate, generate_mock } from 'utility/generate'
import { resolve_endpoint_model_key } from 'utility/resolve'

const { parse, stringify } = JSON

const { port } = parse_options({
  port: {
    type: 'number',
    short: 'p',
    default: 8192,
  },
})

const app = new Hono()

app.use('*', cors())

// log requests
app.use('*', async (c, next) => {
  await next()
  log(format_log(`${c.req.method} ${c.req.path}`, 'info'))
})

app.use('*', serveStatic({ root: '../web/build' }))

let subscribers: Record<id, Set<WebSocket>> = {}

let actions: Record<action, fn> = {
  list: action_list,
  hide,
  subscribe({ thread, client }) {
    if (is(subscribers[thread], 'absent')) {
      subscribers[thread] = set(client)
    } else {
      subscribers[thread].add(client)
    }

    let thread_structure = handle(
      () => deserialize(read(get_thread_file(thread))),
      empty_thread_structure(),
    )

    // todo: ongoing messages
    broadcast('set_thread_structure', { thread, thread_structure }, client)
  },
  unsubscribe({ thread, client }) {
    subscribers[thread]?.delete?.(client)
    // subscribers[thread].delete(client)
  },
  init({ thread, title = '', folder = '', options }) {
    let thread_structure = empty_thread_structure()
    write(get_thread_file(thread), serialize(thread_structure))

    mutate(thread_index_file, (thread_index: thread_index) => {
      thread_index[thread] = {
        title,
        folder,
        creation_time: now().timestamp,
      }
    })

    broadcast('set_thread_structure', { thread, thread_structure })
  },
  send({ thread, prompt, options }) {
    let message = random_id()

    let message_structure: Partial<message_structure> = {
      role: 'user',
      content: prompt,
    }

    let tree
    mutate(get_thread_file(thread), (thread_structure: thread_structure) => {
      append_message(thread_structure, message, message_structure)
      ;({ tree } = thread_structure)
    })

    broadcast('set_message', {
      thread,
      message,
      message_structure,
    })

    broadcast('set_tree', {
      thread,
      tree,
    })
  },
  async generate({ thread, options }) {
    let message = random_id()

    let message_structure: Partial<message_structure> = {
      role: 'assistant',
      content: '',
      reasoning: '',
      start_time: now().timestamp,
    }

    let context, tree

    mutate(get_thread_file(thread), (thread_structure: thread_structure) => {
      context = build_plain_context(thread_structure)

      append_message(thread_structure, message, message_structure)
      ;({ tree } = thread_structure)
    })

    broadcast('set_message', { thread, message, message_structure })

    broadcast('set_tree', {
      thread,
      tree,
    })

    const { endpoint, model, key } = await resolve_endpoint_model_key()

    append_json_log(get_message_log_file(message), 'request', {
      context,
      endpoint,
      model,
    })

    let stream_text = await generate(
      {
        context,
        endpoint,
        model,
        key,
      },
      append,
      finish,
      stream,
    )

    function append(delta: delta) {
      broadcast('append_message', {
        thread,
        message,
        delta,
      })
    }

    function finish(message_structure: message_structure) {
      mutate(get_thread_file(thread), (thread_structure: thread_structure) => {
        thread_structure.messages[message] = message_structure
      })

      broadcast('finish_message', {
        thread,
        message,
        message_structure,
      })

      append_json_log(get_thread_log_file(thread), 'finish_message', {
        message,
        ...message_structure,
      })
    }

    function stream(data) {
      append_json_log(get_message_log_file(message), 'data', data)
    }

    append_json_log(get_message_log_file(message), 'done', stream_text)
  },
}

let non_mutative_actions: action[] = ['subscribe', 'unsubscribe']

function broadcast(
  event: event,
  payload: Extend<{
    thread: id
  }>,
  client?,
) {
  if (is(client, 'absent')) {
    if (is(payload.thread, 'absent')) {
      throw err(
        'it should either broadcast to subscribers of a thread or an explicit client',
      )
    }

    client = subscribers[payload.thread]
  }
  client = list(client)

  map(client, (ws) => {
    ws.send(
      stringify({
        type: 'broadcast',
        event,
        payload,
      }),
    )
  })
}

function respond(request: id, payload: any, client: WebSocket) {
  const ws = client

  append_server_log('respond', payload)

  ws.send(
    stringify({
      type: 'response',
      request,
      payload,
    }),
  )
}

function mutate(file, fn) {
  let file_structure = deserialize(read(file))

  let new_file_structure = fn(file_structure)
  if (is(new_file_structure, 'absent')) {
    // direct mutation
    new_file_structure = file_structure
  }

  write(file, serialize(new_file_structure))
}

app.get(
  '/api/ws',
  upgradeWebSocket(() => ({
    onOpen(_event, ws) {
      log('Client connected')

      append_server_log('Client connected')
    },

    async onMessage(event, ws) {
      const { request, action, payload }: request = parse(event.data)

      log(action, payload)
      append_server_log(action, payload)

      if (has(payload, 'thread') && !has(non_mutative_actions, action)) {
        append_json_log(get_thread_log_file(payload.thread), action, payload)
      }

      if (action == 'subscribe' || action == 'unsubscribe') {
        payload.client = ws
      }

      respond(request, await actions[action](payload), ws)
    },

    onClose() {
      log('Client disconnected')

      append_server_log('Client disconnected')
    },
  })),
)

app.get('*', (c) => {
  const html = handle(() => read('../web/build/index.html'))

  if (is_error(html)) {
    log('web/build/index.html should exist, run web build first')

    return c.text('')
  }

  return c.html(html)
})

const ws = new WebSocketServer({ noServer: true })

serve(
  {
    fetch: app.fetch,
    port,
    websocket: { server: ws },
  },
  (info) => {
    log(`Serve on http://localhost:${info.port}`)
  },
)

declare global {
  type action =
    | 'subscribe'
    | 'unsubscribe'
    | 'init'
    | 'send'
    | 'generate'
    | 'list'
    | 'hide'
  type event =
    | 'set_thread_structure'
    | 'set_tree'
    | 'set_message'
    | 'append_message'
    | 'finish_message'

  type request = {
    type: 'request'
    request: id
    action: action
    payload: any
  }

  type response = {
    type: 'response'
    request: id
    payload: any
  }

  type broadcast = {
    type: 'broadcast'
    event: event
    payload: any
  }

  type append = (delta: delta) => any
  type finish = (message_structure: message_structure) => any
}

function append_json_log(file, type, payload) {
  let time = monotonic()

  append(
    file,
    `${stringify({
      type,
      time,
      payload,
    })}\n`,
  )
}

function append_server_log(message, payload?) {
  if (is(payload, 'present')) {
    append(server_log_file, `${format_log(message)}${serialize(payload)}`)
    // append(server_log_file, `${format_log(message)}\n${serialize(payload)}`)
  } else {
    append(server_log_file, format_log(message))
  }
}

import { serialize, deserialize, config_file, env_file } from 'action/index'
import { random } from 'lib/random'
import { monotonic, now } from 'lib/time'

const { parse, stringify } = JSON

export async function generate(
  { context, endpoint, model, key },
  append: append,
  finish: finish,
  stream: fn = identity,
) {
  let start_time = monotonic(),
    end_time
  let content = '',
    reasoning = ''
  let usage = {}
  let first_append_time: number

  const response = await handle(() =>
    fetch(endpoint, {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${key}`,
        'Content-Type': 'application/json',
      },
      body: stringify({
        model,
        messages: context,
        stream: true,
        stream_options: {
          include_usage: true,
        },
      }),
    }),
  )
  if (is_error(response)) {
    finish(fail('network', response.message))
    return
  }

  if (!response.ok) {
    finish(
      fail(
        'endpoint',
        `${response.status} ${response.statusText}`,
        await handle(() => response.json()),
      ),
    )
    return
  }

  if (!response.body) {
    finish(
      fail(
        'endpoint',
        `endpoint should send response stream`,
        await handle(() => response.json()),
      ),
    )
    return
  }

  const reader = response.body.getReader()
  const decoder = new TextDecoder()

  let stream_text = ''
  let buffer = ''

  while (true) {
    const { value, done } = await reader.read()

    if (done) break

    let current_value = decoder.decode(value, { stream: true })
    buffer += current_value
    stream_text += current_value

    const lines = buffer.split('\n')
    buffer = lines.pop() || ''

    for (let line of lines) {
      line = line.trim()

      // Ignore SSE comments and empty lines
      if (!line || line.startsWith(':')) continue

      if (!line.startsWith('data:')) continue

      const payload_text = line.slice(5).trim()

      if (payload_text == '[DONE]') {
        finish(complete())
        return stream_text
      }

      const payload = parse(payload_text)

      stream(payload)

      const new_content = payload.choices?.[0]?.delta?.content ?? ''
      const new_reasoning = payload.choices?.[0]?.delta?.reasoning ?? ''

      if (new_content || new_reasoning) {
        if (is(first_append_time, 'absent')) {
          first_append_time = monotonic()
        }

        content += new_content
        reasoning += new_reasoning

        let delta = {
          content: new_content,
          reasoning: new_reasoning,
        }

        append(delta)
      }

      if (payload.usage) {
        const { prompt_tokens, completion_tokens, total_tokens } = payload.usage
        usage = {
          prompt_tokens,
          completion_tokens,
          total_tokens,
        }
      }
    }
  }

  // Flush any remaining decoder data
  buffer += decoder.decode()

  finish(complete())

  function fail(
    type: 'network' | 'endpoint',
    message: string,
    payload = response,
  ) {
    end_time = monotonic()

    return {
      has_failed: true,
      role: 'assistant' as const,
      content:
        content +
        '\n```chat_error\n' +
        serialize({
          type,
          message,
          payload,
        }) +
        '```\n',
      start_time,
      end_time,
      model,
    }
  }

  function complete() {
    end_time = monotonic()

    let duration = end_time - (first_append_time ?? start_time)

    let perf = {
      tokens_per_second: (usage?.total_tokens ?? 0) / duration,
      time_to_first_token: first_append_time - start_time,
    }

    // parse tools

    return {
      role: 'assistant' as const,
      content,
      reasoning,
      start_time,
      end_time,
      usage,
      perf,
      model,
    }
  }

  return stream_text
}

export async function generate_mock(
  { context, endpoint, model, key },
  append: append,
  finish: finish,
  stream = identity,
) {
  let start_time = monotonic(),
    end_time
  let content = '',
    reasoning = ''
  let usage = {}
  let first_append_time: number = monotonic() + 1

  let stream_text = 'foo bar'

  for (const i of each(3)) {
    let delta = {
      content: `hello ${now().format()}\n`,
      reasoning: 'some thoughts\n',
    }

    append(delta)

    content += delta.content
    reasoning += delta.reasoning

    await sleep(1)
  }

  finish(complete())

  function complete() {
    end_time = monotonic()

    let duration = end_time - (first_append_time ?? start_time)

    let perf = {
      tokens_per_second: (usage?.total_tokens ?? 0) / duration,
      time_to_first_token: first_append_time - start_time,
    }

    // parse tools

    return {
      role: 'assistant' as const,
      content,
      reasoning,
      start_time,
      end_time,
      usage,
      perf,
      model,
    }
  }

  return stream_text
}

--- thread ---
export function empty_thread_structure(): thread_structure {
  return {
    tree: {
      0: {
        children: [],
      },
    },
    roots: [0],
    focus: 0,
    messages: {},
  }
}

export function append_node(tree: thread_structure['tree'], message: id) {
  let node: node = 0
  while (true) {
    const { children, focus } = tree[node]

    if (focus) {
      node = focus
    } else {
      break
    }
  }

  tree[node].children.push(message)
  tree[node].focus = message

  tree[message] = {
    children: [],
  }

  return tree
}

// set focus

export function build_context(thread_structure: thread_structure) {
  let context = []

  const { tree, messages } = thread_structure

  let node: node = 0
  while (true) {
    const { children, focus } = tree[node]

    if (focus) {
      node = focus

      context.push(messages[node])
    } else {
      break
    }
  }

  return context
}

export function build_plain_context(thread_structure: thread_structure) {
  let context = []

  const { tree, messages } = thread_structure

  let node: node = 0
  while (true) {
    const { children, focus } = tree[node]

    if (focus) {
      node = focus

      const { role, content } = messages[node]

      let plain_message_structure: plain_message_structure = {
        role,
        content,
      }

      context.push(plain_message_structure)
    } else {
      break
    }
  }

  return context
}

export function append_message(
  thread_structure: thread_structure,
  message: id,
  message_structure: Partial<message_structure>,
): thread_structure {
  let { tree, messages } = thread_structure

  tree = append_node(tree, message)

  messages[message] = message_structure

  return {
    ...thread_structure,
    tree,
    messages,
  }
}

