import { Hono } from 'hono'
import { serve, upgradeWebSocket } from '@hono/node-server'
import { WebSocketServer } from 'ws'
import { cors } from 'hono/cors'
import { serveStatic } from '@hono/node-server/serve-static'
import { append, children, read, write } from 'lib/file'
import { format_log } from 'lib/log'
import { parse_options } from 'lib/cli'
// import * as action_index from 'action/index'
import { list as action_list, hide } from 'action/index'
import {
  deserialize,
  get_message_log_file,
  get_thread_file,
  get_thread_log_file,
  serialize,
  server_log_file,
  thread_index_file,
} from 'action/index'
import { monotonic, now } from 'lib/time'
import { random, random_id } from 'lib/random'
import {
  append_message,
  build_plain_context,
  empty_thread_structure,
} from 'utility/thread'
import { generate, generate_mock } from 'utility/generate'
import { resolve_endpoint_model_key } from 'utility/resolve'

const { parse, stringify } = JSON

const { port } = parse_options({
  port: {
    type: 'number',
    short: 'p',
    default: 8192,
  },
})

const app = new Hono()

app.use('*', cors())

// log requests
app.use('*', async (c, next) => {
  await next()
  log(format_log(`${c.req.method} ${c.req.path}`, 'info'))
})

app.use('*', serveStatic({ root: '../web/build' }))

let subscribers: Record<id, Set<WebSocket>> = {}

let actions: Record<action, fn> = {
  list: action_list,
  hide,
  subscribe({ thread, client }) {
    if (is(subscribers[thread], 'absent')) {
      subscribers[thread] = set(client)
    } else {
      subscribers[thread].add(client)
    }

    let thread_structure = handle(
      () => deserialize(read(get_thread_file(thread))),
      empty_thread_structure(),
    )

    // todo: ongoing messages
    broadcast('set_thread_structure', { thread, thread_structure }, client)
  },
  unsubscribe({ thread, client }) {
    subscribers[thread]?.delete?.(client)
    // subscribers[thread].delete(client)
  },
  init({ thread, title = '', folder = '', options }) {
    let thread_structure = empty_thread_structure()
    write(get_thread_file(thread), serialize(thread_structure))

    mutate(thread_index_file, (thread_index: thread_index) => {
      thread_index[thread] = {
        title,
        folder,
        creation_time: now().timestamp,
      }
    })

    broadcast('set_thread_structure', { thread, thread_structure })
  },
  send({ thread, prompt, options }) {
    let message = random_id()

    let message_structure: Partial<message_structure> = {
      role: 'user',
      content: prompt,
    }

    let tree
    mutate(get_thread_file(thread), (thread_structure: thread_structure) => {
      append_message(thread_structure, message, message_structure)
      ;({ tree } = thread_structure)
    })

    broadcast('set_message', {
      thread,
      message,
      message_structure,
    })

    broadcast('set_tree', {
      thread,
      tree,
    })
  },
  async generate({ thread, options }) {
    let message = random_id()

    let message_structure: Partial<message_structure> = {
      role: 'assistant',
      content: '',
      reasoning: '',
      start_time: now().timestamp,
    }

    let context, tree

    mutate(get_thread_file(thread), (thread_structure: thread_structure) => {
      context = build_plain_context(thread_structure)

      append_message(thread_structure, message, message_structure)
      ;({ tree } = thread_structure)
    })

    broadcast('set_message', { thread, message, message_structure })

    broadcast('set_tree', {
      thread,
      tree,
    })

    const { endpoint, model, key } = await resolve_endpoint_model_key()

    append_json_log(get_message_log_file(message), 'request', {
      context,
      endpoint,
      model,
    })

    let stream_text = await generate(
      {
        context,
        endpoint,
        model,
        key,
      },
      append,
      finish,
      stream,
    )

    function append(delta: delta) {
      broadcast('append_message', {
        thread,
        message,
        delta,
      })
    }

    function finish(message_structure: message_structure) {
      mutate(get_thread_file(thread), (thread_structure: thread_structure) => {
        thread_structure.messages[message] = message_structure
      })

      broadcast('finish_message', {
        thread,
        message,
        message_structure,
      })

      append_json_log(get_thread_log_file(thread), 'finish_message', {
        message,
        ...message_structure,
      })
    }

    function stream(data) {
      append_json_log(get_message_log_file(message), 'data', data)
    }

    append_json_log(get_message_log_file(message), 'done', stream_text)
  },
}

let non_mutative_actions: action[] = ['subscribe', 'unsubscribe']

function broadcast(
  event: event,
  payload: Extend<{
    thread: id
  }>,
  client?,
) {
  if (is(client, 'absent')) {
    if (is(payload.thread, 'absent')) {
      throw err(
        'it should either broadcast to subscribers of a thread or an explicit client',
      )
    }

    client = subscribers[payload.thread]
  }
  client = list(client)

  map(client, (ws) => {
    ws.send(
      stringify({
        type: 'broadcast',
        event,
        payload,
      }),
    )
  })
}

function respond(request: id, payload: any, client: WebSocket) {
  const ws = client

  append_server_log('respond', payload)

  ws.send(
    stringify({
      type: 'response',
      request,
      payload,
    }),
  )
}

function mutate(file, fn) {
  let file_structure = deserialize(read(file))

  let new_file_structure = fn(file_structure)
  if (is(new_file_structure, 'absent')) {
    // direct mutation
    new_file_structure = file_structure
  }

  write(file, serialize(new_file_structure))
}

app.get(
  '/api/ws',
  upgradeWebSocket(() => ({
    onOpen(_event, ws) {
      log('Client connected')

      append_server_log('Client connected')
    },

    async onMessage(event, ws) {
      const { request, action, payload }: request = parse(event.data)

      log(action, payload)
      append_server_log(action, payload)

      if (has(payload, 'thread') && !has(non_mutative_actions, action)) {
        append_json_log(get_thread_log_file(payload.thread), action, payload)
      }

      if (action == 'subscribe' || action == 'unsubscribe') {
        payload.client = ws
      }

      respond(request, await actions[action](payload), ws)
    },

    onClose() {
      log('Client disconnected')

      append_server_log('Client disconnected')
    },
  })),
)

app.get('*', (c) => {
  const html = handle(() => read('../web/build/index.html'))

  if (is_error(html)) {
    log('web/build/index.html should exist, run web build first')

    return c.text('')
  }

  return c.html(html)
})

const ws = new WebSocketServer({ noServer: true })

serve(
  {
    fetch: app.fetch,
    port,
    websocket: { server: ws },
  },
  (info) => {
    log(`Serve on http://localhost:${info.port}`)
  },
)

declare global {
  type action =
    | 'subscribe'
    | 'unsubscribe'
    | 'init'
    | 'send'
    | 'generate'
    | 'list'
    | 'hide'
  type event =
    | 'set_thread_structure'
    | 'set_tree'
    | 'set_message'
    | 'append_message'
    | 'finish_message'

  type request = {
    type: 'request'
    request: id
    action: action
    payload: any
  }

  type response = {
    type: 'response'
    request: id
    payload: any
  }

  type broadcast = {
    type: 'broadcast'
    event: event
    payload: any
  }

  type append = (delta: delta) => any
  type finish = (message_structure: message_structure) => any
}

function append_json_log(file, type, payload) {
  let time = monotonic()

  append(
    file,
    `${stringify({
      type,
      time,
      payload,
    })}\n`,
  )
}

function append_server_log(message, payload?) {
  if (is(payload, 'present')) {
    append(server_log_file, `${format_log(message)}${serialize(payload)}`)
    // append(server_log_file, `${format_log(message)}\n${serialize(payload)}`)
  } else {
    append(server_log_file, format_log(message))
  }
}

import { use_sync_theme } from 'lib/web/use sync theme'
import { use_window_active } from 'lib/web/use window active'
import 'web/design/app.css'
import 'web/design/utilitarian.css'

import { sidebar } from './sidebar'
import { conversation } from './conversation'
import { random_id } from 'lib/random'

import { build_context, empty_thread_structure } from 'utility/thread'
import { build_flat_hierarchy } from 'web/utility/thread_hierarchy'
import { text } from 'web/utility/text'
import { scroll_by } from 'web/utility/scroll'
import { trim } from 'web/utility/string'
import { create_websocket_client } from 'web/utility/websocket'
import { modal_prompt } from './modal_prompt'
import { modal_search } from './modal_search'
import { init_localstorage_prefix } from 'lib/web/state'

const max_title_length = 65 * 2

init_localstorage_prefix('humility')

export const use_sidebar_open = s(false, {
  localstorage: 'sidebar',
})

export const use_display_thread = s(nil as id | nil, {
  url_param: 'thread',
})
export const use_thread = s(nil as id | nil)

export const use_folder = s('', {
  localstorage: 'folder',
  // localstorage: 'cwd',
})

export function app() {
  use_sync_theme('system')
  use_window_active()

  const [prompt, set_prompt] = use_state('')

  const [folder, set_folder] = use_folder()
  const [expanded_folders, set_expanded_folders] = use_state<string[]>([])
  const [thread_structure, set_thread_structure] = use_state<thread_structure>(
    empty_thread_structure(),
  )
  const [thread_index, set_thread_index] = use_state<thread_index | nil>(nil)
  const [thread, set_thread] = use_thread()
  const [display_thread, set_display_thread] = use_display_thread()

  const [should_show_reasoning, set_should_show_reasoning] = use_state(false)

  const [modal_prompt_open, set_modal_prompt_open] = use_state(false)

  const [should_use_vimium, set_should_use_vimium] = use_state(true)

  const [sidebar_open, set_sidebar_open] = use_sidebar_open()

  let is_new_thread = thread_index != nil && !has(thread_index, thread)

  const content = use_ref()
  const prompt_field = use_ref()

  const [modal_prompt_initial_value, set_modal_prompt_initial_value] =
    use_state()
  const modal_prompt_set_value = use_ref()
  const modal_prompt_placeholder = use_ref()

  function open_prompt_modal({ value, set_value, placeholder }) {
    set_modal_prompt_open(true)

    set_modal_prompt_initial_value(value)
    modal_prompt_set_value.current = set_value
    modal_prompt_placeholder.current = placeholder
  }

  const websocket_ref = use_ref<ReturnType<typeof create_websocket_client> | nil>(
    nil,
  )
  if (!websocket_ref.current) {
    websocket_ref.current = create_websocket_client()
  }
  const websocket = websocket_ref.current

  function use_vimium(on) {
    const jk_scroll_distance = 60
    const du_scroll_percentage = 0.5
    const space_scroll_percentage = 0.9
    const distances = {
      j: jk_scroll_distance,
      k: -jk_scroll_distance,
      d: du_scroll_percentage,
      u: -du_scroll_percentage,
      space: space_scroll_percentage,
      'shift+space': -space_scroll_percentage,
    }
    const field_tags = ['input', 'textarea']

    function is_inserting() {
      return has(field_tags, document.activeElement?.tagName.toLowerCase())
    }

    use_keyboard(
      'esc',
      () => {
        document.activeElement?.blur()
      },
      {
        when: () => on && is_inserting(),
      },
    )

    use_keyboard('i', () => prompt_field?.current?.focus(), {
      when: () => on && !is_inserting(),
    })

    map(distances, ([key, distance]) =>
      use_keyboard(key, () => scroll_by(content, distance), {
        when: () => on && !is_inserting(),
      }),
    )
  }

  use_vimium(should_use_vimium)

  // set thread url param: nil for new thread, otherwise existing
  // for simplicity, it technically subscribes a (random) thread regardless
  use_effect(() => {
    set_thread(display_thread ?? random_id())
  }, [display_thread])
  use_effect(() => {
    if (has(thread_index, thread)) {
      set_display_thread(thread)
    } else if (is_new_thread) {
      set_display_thread(nil)
    }
  }, [thread, is_new_thread])

  let commands = {
    new_thread() {
      set_thread(random_id())
    },
    change_current_folder() {
      open_prompt_modal({
        value: folder,
        set_value(folder: string) {
          set_folder(trim(trim(folder), '/'))
        },
        placeholder: text('folder'),
      })
    },
    toggle_sidebar() {
      set_sidebar_open()
    },
  }

  type shortcut = {
    command: keyof typeof commands
    key: string
    when?: fn
  }

  let shortcuts: shortcut[] = [
    {
      command: 'toggle_sidebar',
      key: 'ctrl+b',
    },
    {
      command: 'new_thread',
      key: 'alt+n',
    },
  ]

  async function hide_thread(id: id) {
    websocket.perform('hide', { thread: id })
    set_thread_index((index) => {
      index[id].is_hidden = true
    })
    if (thread == id) {
      commands.new_thread()
    }
  }

  let controls = {
    async send_prompt() {
      if (entries(thread_structure.messages).length == 0) {
        await websocket.perform('init', {
          thread,
          title: prompt.slice(0, max_title_length),
          folder,
        })

        set_thread_index(websocket.perform('list'))
      }

      await websocket.perform('send', {
        thread,
        prompt,
        options: {},
      })

      set_prompt('')

      await websocket.perform('generate', { thread })
    },
    toggle_folder(folder) {
      let folders = set(expanded_folders)

      if (has(folders, folder)) {
        folders.delete(folder)
      } else {
        folders.add(folder)
      }

      set_expanded_folders(array(folders))
    },
  }

  let broadcasts: Record<event, fn> = {
    set_thread_structure({ thread_structure }) {
      set_thread_structure(thread_structure)
    },
    set_tree({ tree }) {
      set_thread_structure((t) => {
        t.tree = tree
      })
    },
    set_message({ message, message_structure }) {
      set_thread_structure((t) => {
        t.messages[message] = message_structure
      })
    },
    append_message({ message, delta }) {
      const { content = '', reasoning = '' } = delta

      set_thread_structure((t) => {
        t.messages[message].content =
          (t.messages[message].content ?? '') + content
        t.messages[message].reasoning =
          (t.messages[message].reasoning ?? '') + reasoning
        // t.messages[message].content += content
        // t.messages[message].reasoning += reasoning
      })
    },
    finish_message({ message, message_structure }) {
      set_thread_structure((t) => {
        t.messages[message] = message_structure
      })
    },
  }

  // open websocket
  use_mount(() => {
    function receive_message(e: MessageEvent) {
      const data = JSON.parse(e.data)

      const { type, payload } = data

      log('receive', type, payload)

      if (type == 'response') {
        const { request } = data
        websocket.receive_response(request, payload)
        return
      }

      log('receive', type, payload)

      if (type == 'broadcast') {
        const { event } = data
        broadcasts[event](payload)
      }
    }

    websocket.connect(receive_message)
  })

  // list threads on sidebar
  use_mount(() => {
    set_thread_index(websocket.perform('list'))
    // set_threads(post('list'))
  })

  // subscribe broadcast of current thread
  use_effect(() => {
    if (!thread) {
      return
    }

    websocket.perform('subscribe', { thread })

    return () => websocket.perform('unsubscribe', { thread })
  }, [thread])

  // bind shortcuts for controls
  use_keyboard('enter', controls.send_prompt, {
    when: () => prompt && document.activeElement == prompt_field.current,
  })
  // disable entering on empty prompt
  use_keyboard('enter', identity, {
    when: () => !prompt && document.activeElement == prompt_field.current,
  })

  // focus prompt when thread change
  use_effect(() => {
    // you may want to just browse existing threads
    if (is_new_thread) {
      prompt_field.current?.focus()
    }
  }, [thread, is_new_thread])

  // expand all folders on path to cwd
  use_effect(() => {
    let folders = set(expanded_folders)

    let dirs = folder.split('/')

    for (const i of each(1, dirs.length)) {
      folders.add(dirs.slice(0, i).join('/'))
    }

    set_expanded_folders(array(folders))
  }, [folder])

  let flat_hierarchy = build_flat_hierarchy(
    thread_index ?? {},
    expanded_folders,
  )

  return h(
    h('title.', 'Humility'),
    h(
      'app',
      sidebar_open &&
        h(sidebar, {
          threads: flat_hierarchy,
          current_thread: thread,
          on_new_thread: commands.new_thread,
          on_select_thread: set_thread,
          on_hide_thread: hide_thread,
          on_toggle_folder: controls.toggle_folder,
        }),
      h(conversation, {
        messages: build_context(thread_structure),
        folder,
        is_new_thread,
        prompt,
        set_prompt,
        should_show_reasoning,
        prompt_ref: prompt_field,
        content_ref: content,
      }),
      h(modal_prompt, {
        open: modal_prompt_open,
        set_open: set_modal_prompt_open,
        initial_value: modal_prompt_initial_value,
        set_value: modal_prompt_set_value.current,
        placeholder: modal_prompt_placeholder.current,
      }),
      h(modal_search, {
        files: map(
          thread_index ?? {},
          ([id, { title, folder = '', is_hidden }]) => {
            if (!is_hidden) {
              return {
                label: title,
                info: folder,
                fn() {
                  set_thread(id)
                },
              }
            }
          },
        ),
        commands,
        shortcuts,
      }),
    ),
  )
}

