export const tool_registry: Record<string, tool_definition> = {
  bash: {
    instructions: `Run a shell command with the bash tool. Call it by replying with a fenced tool block containing one YAML mapping from bash to an object with a command field, for example:\n\n\`\`\`tool\nbash:\n  command: pwd\n\`\`\``,
    async run(args, append) {
      const command = args.command
      if (typeof command !== 'string') {
        throw new Error('bash tool requires a string command')
      }

      return await new Promise((resolve, reject) => {
        const child = spawn('bash', ['-lc', command])
        let output = ''

        child.stdout.on('data', (chunk) => {
          const content = chunk.toString()
          output += content
          append({ content })
        })

        child.stderr.on('data', (chunk) => {
          const content = chunk.toString()
          output += content
          append({ content })
        })

        child.once('error', reject)
        child.once('close', (code, signal) => {
          if (code !== 0) {
            const status = `\n[process exited with ${code ?? signal}]`
            output += status
            append({ content: status })
          }
          resolve(output)
        })
      })
    },
  },
}

export function parse_tool_calls(content: string): tool_call[] {
  const calls: tool_call[] = []
  const blocks = content.matchAll(/```tool[ \t]*\r?\n([\s\S]*?)```/g)

  for (const [, source] of blocks) {
    try {
      const value = parse_yaml(source)
      if (!is_record(value)) continue

      if (typeof value.tool === 'string' && is_record(value.args)) {
        calls.push({ tool: value.tool, args: value.args })
        continue
      }

      const names = Object.keys(value)
      if (names.length != 1 || !is_record(value[names[0]])) continue

      calls.push({ tool: names[0], args: value[names[0]] })
    } catch {}
  }

  return calls
}

export function is_record(value: any): value is Record<string, any> {
  return value != null && typeof value == 'object' && !Array.isArray(value)
}

import { tool_registry } from './tools'

export function empty_thread_structure(): thread_structure {
  return {
    tree: {
      0: {
        children: [],
      },
    },
    roots: {
      0: {
        tools: ['bash'],
        pending_tools: {},
      },
    },
    messages: {},
  }
}

export function append_node(tree: thread_structure['tree'], message: id) {
  let node: node = 0

  while (tree[node]?.focus) {
    node = tree[node].focus!
  }

  tree[node].children.push(message)
  tree[node].focus = message
  tree[message] = {
    children: [],
  }

  return tree
}

export function build_context(thread_structure: thread_structure) {
  return build_path(thread_structure).map((node) => thread_structure.messages[node])
}

export function build_plain_context(thread_structure: thread_structure) {
  const root_config = thread_structure.roots[0] ?? {}
  const tool_instructions = (root_config.tools ?? [])
    .map((name) => tool_registry[name]?.instructions)
    .filter(Boolean)
  const system_prompt = [root_config.system_prompt, ...tool_instructions]
    .filter(Boolean)
    .join('\n\n')

  const context: plain_message_structure[] = []

  if (system_prompt) {
    context.push({ role: 'system', content: system_prompt })
  }

  for (const node of build_path(thread_structure)) {
    const message = thread_structure.messages[node]
    if (!message) continue

    const role = message.role == 'tool' ? 'user' : message.role
    const previous = context.at(-1)

    if (previous?.role == role) {
      previous.content += `\n\n${message.content ?? ''}`
    } else {
      context.push({
        role,
        content: message.content ?? '',
      })
    }
  }

  return context
}

export function append_message(
  thread_structure: thread_structure,
  message: id,
  message_structure: Partial<message_structure>,
): thread_structure {
  append_node(thread_structure.tree, message)
  thread_structure.messages[message] = message_structure

  return thread_structure
}

function build_path(thread_structure: thread_structure): node[] {
  const root: root = 0
  let node: node = thread_structure.roots[root]?.start ?? root
  const path: node[] = node == root ? [] : [node]

  while (thread_structure.tree[node]?.focus) {
    node = thread_structure.tree[node].focus!
    path.push(node)
  }

  return path
}

