)

declare global {
  type action =
    | 'subscribe'
    | 'unsubscribe'
    | 'init'
    | 'send'
    | 'generate'
    | 'call_tool'
    | 'list'
    | 'hide'

  type event =
    | 'set_thread_structure'
    | 'set_tree'
    | 'set_message'
    | 'set_pending_tools'
    | 'set_active'
    | 'append_message'
    | 'finish_message'

  type request = {
    type: 'request'
    request: id
    action: action
    payload: any
  }

  type response = {
    type: 'response'
    request: id
    payload: any
  }

  type broadcast = {
    type: 'broadcast'
    event: event
    payload: any
  }

  type append = (delta: delta) => any
  type finish = (message_structure: message_structure) => any
}

function append_json_log(file, type, payload) {
  append(
    file,
    `${stringify({
      type,
      time: monotonic(),
      payload,
    })}\n`,
  )
}

function append_server_log(message, payload?) {
  if (is(payload, 'present')) {
    append(server_log_file, `${format_log(message)}${serialize(payload)}`)
  } else {
    append(server_log_file, format_log(message))
  }
}

